    /// <summary>Create a window with the specified dimensions and flags.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CreateWindow</c>.</para>
    /// <para>
    /// The window size is a request and may be different than expected based on the desktop layout and window manager
    /// policies. Your application should be prepared to handle a window of any size.
    /// </para>
    /// <para><c>flags</c> may be any of the following OR'd together:</para>
    /// <list type="bullet">
    /// <item><description><c>SDL_WINDOW_FULLSCREEN</c>: fullscreen window at desktop resolution</description></item>
    /// <item><description><c>SDL_WINDOW_OPENGL</c>: window usable with an OpenGL context</description></item>
    /// <item><description><c>SDL_WINDOW_HIDDEN</c>: window is not visible</description></item>
    /// <item><description><c>SDL_WINDOW_BORDERLESS</c>: no window decoration</description></item>
    /// <item><description><c>SDL_WINDOW_RESIZABLE</c>: window can be resized</description></item>
    /// <item><description><c>SDL_WINDOW_MINIMIZED</c>: window is minimized</description></item>
    /// <item><description><c>SDL_WINDOW_MAXIMIZED</c>: window is maximized</description></item>
    /// <item><description><c>SDL_WINDOW_MOUSE_GRABBED</c>: window has grabbed mouse focus</description></item>
    /// <item><description><c>SDL_WINDOW_INPUT_FOCUS</c>: window has input focus</description></item>
    /// <item><description><c>SDL_WINDOW_MOUSE_FOCUS</c>: window has mouse focus</description></item>
    /// <item><description><c>SDL_WINDOW_EXTERNAL</c>: window not created by SDL</description></item>
    /// <item><description><c>SDL_WINDOW_MODAL</c>: window is modal</description></item>
    /// <item>
    /// <description><c>SDL_WINDOW_HIGH_PIXEL_DENSITY</c>: window uses high pixel density back buffer if
    /// possible</description>
    /// </item>
    /// <item>
    /// <description><c>SDL_WINDOW_MOUSE_CAPTURE</c>: window has mouse captured (unrelated to
    /// MOUSE_GRABBED)</description>
    /// </item>
    /// <item><description><c>SDL_WINDOW_ALWAYS_ON_TOP</c>: window should always be above others</description></item>
    /// <item>
    /// <description><c>SDL_WINDOW_UTILITY</c>: window should be treated as a utility window, not showing in the task
    /// bar and window list</description>
    /// </item>
    /// <item>
    /// <description><c>SDL_WINDOW_TOOLTIP</c>: window should be treated as a tooltip and does not get mouse or keyboard
    /// focus, requires a parent window</description>
    /// </item>
    /// <item>
    /// <description><c>SDL_WINDOW_POPUP_MENU</c>: window should be treated as a popup menu, requires a parent
    /// window</description>
    /// </item>
    /// <item><description><c>SDL_WINDOW_KEYBOARD_GRABBED</c>: window has grabbed keyboard input</description></item>
    /// <item><description><c>SDL_WINDOW_VULKAN</c>: window usable with a Vulkan instance</description></item>
    /// <item><description><c>SDL_WINDOW_METAL</c>: window usable with a Metal instance</description></item>
    /// <item><description><c>SDL_WINDOW_TRANSPARENT</c>: window with transparent buffer</description></item>
    /// <item><description><c>SDL_WINDOW_NOT_FOCUSABLE</c>: window should not be focusable</description></item>
    /// </list>
    /// <para>
    /// The SDL_Window will be shown if SDL_WINDOW_HIDDEN is not set. If hidden at creation time, SDL_ShowWindow() can
    /// be used to show it later.
    /// </para>
    /// <para>
    /// On Apple's macOS, you <b>must</b> set the NSHighResolutionCapable Info.plist property to YES, otherwise you will
    /// not receive a High-DPI OpenGL canvas.
    /// </para>
    /// <para>
    /// The window pixel size may differ from its window coordinate size if the window is on a high pixel density
    /// display. Use SDL_GetWindowSize() to query the client area's size in window coordinates, and
    /// SDL_GetWindowSizeInPixels() or SDL_GetRenderOutputSize() to query the drawable size in pixels. Note that the
    /// drawable size can vary after the window is created and should be queried again if you get an
    /// SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED event.
    /// </para>
    /// <para>
    /// If the window is created with any of the SDL_WINDOW_OPENGL or SDL_WINDOW_VULKAN flags, then the corresponding
    /// LoadLibrary function (SDL_GL_LoadLibrary or SDL_Vulkan_LoadLibrary) is called and the corresponding
    /// UnloadLibrary function is called by SDL_DestroyWindow().
    /// </para>
    /// <para>
    /// If SDL_WINDOW_VULKAN is specified and there isn't a working Vulkan driver, SDL_CreateWindow() will fail, because
    /// SDL_Vulkan_LoadLibrary() will fail.
    /// </para>
    /// <para>
    /// If SDL_WINDOW_METAL is specified on an OS that does not support Metal, SDL_CreateWindow() will fail.
    /// </para>
    /// <para>
    /// If you intend to use this window with an SDL_Renderer, you should use SDL_CreateWindowAndRenderer() instead of
    /// this function, to avoid window flicker.
    /// </para>
    /// <para>
    /// On non-Apple devices, SDL requires you to either not link to the Vulkan loader or link to a dynamic library
    /// version. This limitation may be removed in a future version of SDL.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_CreateWindowAndRenderer</c>, <c>SDL_CreatePopupWindow</c>,
    /// <c>SDL_CreateWindowWithProperties</c>, <c>SDL_DestroyWindow</c>.
    /// </para>
    /// </remarks>
    /// <param name="title">the title of the window, in UTF-8 encoding.</param>
    /// <param name="w">the width of the window.</param>
    /// <param name="h">the height of the window.</param>
    /// <param name="flags">0, or one or more SDL_WindowFlags OR'd together.</param>
    /// <returns>the window that was created or NULL on failure; call SDL_GetError() for more information.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_CreateWindow")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial Window CreateWindow(byte* title, int w, int h, WindowFlags flags);

